  rNotDirect: m => `${m} can’t be reached with splitters alone`, rLoopFits: () => 'the matrix loop already fits on the belt; splitting first only adds pieces', rDirect: m => `${m} splits directly; a loop or sink only adds pieces`,
  rOneInput: 'with 1 input it’s the same as the matrix', rShape: 'needs 2 or more outputs', rBpShape: 'shape doesn’t match',
  rLimit: (seg, rate, belt) => `bottleneck: ${seg} (${rate}/min) exceeds ${belt}`, rNoLimit: 'no bottleneck',
  whyTitle: 'Why this design', whyNotTitle: 'Why it isn’t the best',
  whyBp: (n, m) => `You already have the ${n}→${m} blueprint: just paste it instead of building piece by piece.`,
  whyOnly: 'It’s the only design that fits this shape.',
