  dkButterfly: 'butterfly', dkButterflyLoop: 'looped butterfly', dkButterflySink: 'butterfly with sink',
  dsButterfly: 'Mixes belts in pairs (or threes) over rounds: each block takes 2 belts and returns 2 at the average. After every round, all belts are equal. A missing input becomes an empty lane (3→4 uses the 4-lane butterfly); for 4→4 and 8→8 it uses far fewer pieces than the matrix and stacks well.',
  dsButterflyLoop: 'Butterfly for 5, 7…: uses the next lane count made of 2s and 3s (6 for 5, 8 for 7) and the spare lane loops back to its own start. 5→5 takes 24 pieces, against 35 for the looped matrix.',
  rButterfly: 'needs 2 or more inputs and outputs (with 1 input it’s the splitter tree; with 1 output, just mergers)',
  rBfExtra: (m, k) => `uses ${k} lanes for ${m} outputs: pick the looped or the sink version`,
  segBfPart: s => `Round ${s}: each part`, segBfOut: s => `Round ${s}: each belt after the merger`,
  segBfLoop: 'Loop return (each lane)', segBfLoopIn: 'Lane start (input + return)', bfEmpty: 'empty', bfReturn: '↺ return',
  styleTitle: 'Build', styleBestTip: 'The best design for this shape is in this tab',
  styleBetter: (tab, name, pieces, rate) => `For this shape, the best design is under ${tab}: ${name}, ${pieces} pieces and ${rate}/min per output.`, styleNormal: 'Normal', styleButterfly: 'Butterfly', style3d: '3D',
  tipStyle: 'Normal: flat designs (matrix, funnel, with a loop or sink). Butterfly: mixes belts in pairs over rounds; works for any N→M from 2→2 up, with empty lanes or spare lanes on a loop or sink, and uses fewer pieces for 4→4, 8→8. 3D: the chosen balancer in a scene you can spin, as towers (each layer’s pieces stacked) or floors, with a hologram step by step.',
  styleNone: 'The butterfly needs at least 2 inputs and 2 outputs: with 1 input it’s the splitter tree, with 1 output it’s just mergers. Use Normal or 3D.',
  thLifts: 'Lifts',
  stBfSplit: (round, n, r) => `Round ${round}: a splitter into ${r} on ${n > 1 ? `each of the ${n} lanes that carry items` : 'the lane that carries items'}.`,
  stBfFan: (round, list) => `Round ${round}: no mergers. Each splitter output goes straight to one lane, filling the empty lanes (lane ← splitter on lane): ${list}.`,
  stBfMerge: (round, joins, pass) => `Round ${round}: a merger on each lane, joining one output from each listed splitter (lane ← splitters on lanes): ${joins}. Lanes joined together leave equal.` + (pass ? ` No merger, a single part: ${pass}.` : ''),
  stBfLoopBack: (k, lanes, m) => `${k > 1 ? `Lanes ${lanes} are spare and go` : `Lane ${lanes} is spare and goes`} back to ${k > 1 ? 'their own start' : 'its own start'} (loop). What comes back is mixed again, so the ${m} outputs are equal.`,
  stLevel3d: (mode, lv, sp, ways, mg, up, down) => `${{ towers: 'Tower', floors: 'Floor', flat: 'Column' }[mode]} ${lv}: ` + [sp ? `${sp} splitter${sp > 1 ? 's' : ''} into ${ways}` : '', mg ? `${mg} merger${mg > 1 ? 's' : ''}` : ''].filter(Boolean).join(' and ') + (up ? `; ${up > 1 ? `${up} belts arrive` : '1 belt arrives'} by lift` : '') + (down ? `; ${down > 1 ? `${down} loop returns leave` : '1 loop return leaves'} from here` : '') + '.',
